	public void testSendQueryExplanationReappliesExplainLevelVisibility(String factoryName, MockServerClient client)
			throws Exception {
		this.factoryName = factoryName;
		this.sparqlSession = createProtocolSession();
		client.when(
				request()
						.withMethod("POST")
						.withPath("/rdf4j-server/repositories/test")
						.withQueryStringParameter("explain", "Executed"),
				Times.once())
				.respond(
						response()
								.withBody("{\"type\":\"Projection\",\"resultSizeActual\":3,"
										+ "\"plans\":[{\"type\":\"Join (JoinIterator)\",\"resultSizeActual\":3,"
										+ "\"plans\":["
										+ "{\"type\":\"StatementPattern\",\"resultSizeEstimate\":6.0,\"resultSizeActual\":6,"
										+ "\"stringMetricsActual\":{\"indexName\":\"ospc\"}},"
										+ "{\"type\":\"StatementPattern\",\"resultSizeEstimate\":6.0,\"resultSizeActual\":3,"
										+ "\"stringMetricsActual\":{\"indexName\":\"spoc\"}}]}]}")
								.withContentType(MediaType.APPLICATION_JSON)
				);

		Explanation explanation = getRDF4JSession().sendQueryExplanation(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s ?p ?o }", null, null, true, 0, Explanation.Level.Executed);

		assertThat(explanation.toString()).contains("indexName=spoc");
		assertThat(explanation.toString()).doesNotContain("sampleCountActual=");
		assertThat(explanation.toString()).doesNotContain("varianceActual=");
		assertThat(explanation.toString()).doesNotContain("stddevActual=");
		assertThat(explanation.toString()).doesNotContain("confidenceScoreActual=");
	}

